// Prüfer B8: Werkzeugbereich als Bild (1440 und 390), Überlauf messen
import { chromium } from "playwright";
const [basis, out, ...pfade] = process.argv.slice(2);
const browser = await chromium.launch();
for (const w of [1440, 390]) {
  const page = await browser.newPage({ viewport: { width: w, height: w < 700 ? 844 : 900 } });
  let banner = false;
  for (const pfad of pfade) {
    const fehler = [];
    page.on("pageerror", (e) => fehler.push(String(e)));
    await page.goto(basis + pfad, { waitUntil: "load", timeout: 180000 });
    await page.waitForTimeout(2000);
    if (!banner) await page.locator("button", { hasText: "Nur notwendige" }).first().click({ timeout: 4000 }).then(() => (banner = true)).catch(() => {});
    const ueber = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
    const name = pfad.replace(/^\//, "").replace(/\//g, "_");
    const ziel = page.locator("#rechner, [id=rechner], main section").nth(1);
    await page.evaluate(() => window.scrollTo(0, 0));
    const hoehe = await page.evaluate(() => document.body.scrollHeight);
    await page.screenshot({ path: `${out}/t${w}-${name}.png`, fullPage: true, clip: { x: 0, y: w < 700 ? 600 : 650, width: w, height: Math.min(w < 700 ? 3600 : 2200, hoehe - 700) } });
    console.log(w, pfad, "ueberlauf", ueber, "fehler", fehler.length, fehler[0] || "");
    void ziel;
  }
  await page.close();
}
await browser.close();

